		bLoaded &= (_glUniformMatrix4fv = OGL_LOAD(glUniformMatrix4fv)) != nullptr;
		bLoaded &= (_glActiveTexture = OGL_LOAD(glActiveTexture)) != nullptr;
		bLoaded &= (_glGenFramebuffers = OGL_LOAD(glGenFramebuffers)) != nullptr;
